<?php
declare(strict_types=1);require_once __DIR__.'/config/ai_analytics.php';
try{$pdo=role_portal_db();role_portal_ensure($pdo);aia_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user||!in_array((string)($user['role_code']??''),['admin'],true)){http_response_code(403);exit('Access denied.');}$orgId=pscms_org_id($pdo);$format=(string)($_GET['format']??'json');$site=pscms_payload($pdo);$answers=aia_verified_answers($pdo,$orgId);$content=array_filter($site['content'],static fn(string $k):bool=>!str_contains($k,'chat_url'),ARRAY_FILTER_USE_KEY);$pack=['version'=>'HWC-AI-TRAINING-2.0','exported_at'=>gmdate('c'),'instructions'=>$content['global_ai_instructions']??'','fallback'=>$content['global_ai_fallback']??'','club'=>$content,'services'=>$site['services'],'verified_answers'=>$answers,'policies'=>['General wellness education only.','Never diagnose or prescribe treatment.','Never guarantee wellness or product results.','Use only verified public club information.','Offer human support when confirmation is required.']];
 if($format==='text'){header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="hwc-ai-training.txt"');echo "HEALTHCARE WELLNESS CLUB — VERIFIED AI TRAINING PACK\n\nINSTRUCTIONS\n".$pack['instructions']."\n\nFALLBACK\n".$pack['fallback']."\n\nCLUB\n".json_encode($content,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n\nSERVICES\n".json_encode($site['services'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n\nVERIFIED ANSWERS\n".json_encode($answers,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n\nPOLICIES\n- ".implode("\n- ",$pack['policies']);}else{header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="hwc-ai-training.json"');echo json_encode($pack,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);}
}catch(Throwable $e){http_response_code(500);echo 'Training export unavailable.';}
